<script setup lang="ts">
const { from, to, today, report, loading, error, canView, load, apply } = useAdminBillingReport()
const money = (amount: number, currency: string) => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(amount)
const credits = (units: number) => (units / 100).toLocaleString(undefined, { maximumFractionDigits: 2 })
</script>
<template>
  <section v-if="canView" class="surface space-y-5 p-5 sm:p-6">
    <div><h2 class="text-lg font-semibold">Billing report</h2><p class="mt-1 text-sm text-[var(--muted)]">Purchases, credit movements and estimated provider costs.</p></div>
    <form class="flex flex-wrap items-end gap-3" @submit.prevent="apply"><label class="billing-label">From<input v-model="from" required type="date" :max="to" class="billing-input" :disabled="loading"></label><label class="billing-label">To<input v-model="to" required type="date" :min="from" :max="today" class="billing-input" :disabled="loading"></label><button type="submit" class="button-secondary" :disabled="loading">{{ loading ? 'Loading…' : 'View report' }}</button></form>
    <p v-if="error" class="rounded-xl bg-red-50 p-4 text-sm text-red-700" role="alert">{{ error }} <button type="button" class="underline" @click="load">Retry</button></p>
    <p v-if="loading" class="py-6 text-sm text-[var(--muted)]" role="status">Loading billing report…</p>
    <template v-else-if="report">
      <p v-if="!report.payments.length && !report.usage.length && !report.ledger.length" class="rounded-xl bg-[var(--page)] p-6 text-sm text-[var(--muted)]">No billing activity in this period.</p>
      <div v-if="report.payments.length" class="grid gap-4 sm:grid-cols-2"><div v-for="payment in report.payments" :key="payment.currency" class="rounded-xl border border-indigo-100 bg-indigo-50/50 p-5"><p class="text-xs font-semibold tracking-wider text-indigo-700 uppercase">{{ payment.currency }} purchases</p><p class="mt-2 text-2xl font-semibold">{{ money(payment.revenue_minor / 100, payment.currency) }}</p><p class="mt-2 text-sm text-[var(--muted)]">{{ payment.purchases }} purchases · {{ credits(payment.credit_units) }} credits</p><p class="mt-1 text-xs text-[var(--muted)]">Known gateway fees: {{ money(payment.known_fees_minor / 100, payment.currency) }}</p></div></div>
      <div v-if="report.usage.length" class="overflow-x-auto"><h3 class="mb-3 text-sm font-semibold">Usage &amp; provider costs</h3><table class="w-full whitespace-nowrap text-left text-sm"><thead class="bg-[var(--page)] text-xs text-[var(--muted)]"><tr><th class="p-3">Activity / model</th><th class="p-3">Status</th><th class="p-3">Jobs</th><th class="p-3">Credits</th><th class="p-3">Estimated cost</th></tr></thead><tbody class="divide-y divide-[var(--line)]"><tr v-for="(usage, index) in report.usage" :key="index"><td class="p-3"><p>{{ usage.activity.replaceAll('_', ' ') }}</p><p class="mt-1 text-xs text-[var(--muted)]">{{ usage.provider }} · {{ usage.model }}</p></td><td class="p-3">{{ usage.status }}</td><td class="p-3">{{ usage.jobs }}</td><td class="p-3">{{ credits(usage.credit_units) }}</td><td class="p-3"><p>{{ usage.estimated_provider_cost_micros !== null && usage.provider_currency ? money(usage.estimated_provider_cost_micros / 1000000, usage.provider_currency) : 'Unavailable' }}</p><p class="mt-1 text-xs text-[var(--muted)]">{{ usage.costed_jobs }} of {{ usage.jobs }} jobs costed</p></td></tr></tbody></table></div>
      <div v-if="report.ledger.length"><h3 class="mb-3 text-sm font-semibold">Credit movements</h3><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><div v-for="entry in report.ledger" :key="entry.kind" class="rounded-xl border border-[var(--line)] p-4"><p class="text-xs text-[var(--muted)]">{{ entry.kind.replaceAll('_', ' ') }}</p><p class="mt-1 font-semibold">{{ credits(entry.credit_units) }} credits</p><p class="mt-1 text-xs text-[var(--muted)]">{{ entry.entries }} entries</p></div></div></div>
      <p class="text-xs leading-5 text-[var(--muted)]">Currencies are reported separately. Released credits are returned wallet credits. Provider costs are estimates, not invoices. Purchases use payment date; usage uses its latest update date.</p>
    </template>
  </section>
</template>
